// sshbox — tiny SSH/SFTP CLI for BoxVision remote training.
//
// Replaces sshpass + scp + ad-hoc shell scripts with a single static binary that
// reads credentials from env (never argv) and supports the deploy flows we need:
// inspect, run, upload, and a higher-level deploy.
//
//   SSHBOX_HOST=192.0.2.10 SSHBOX_USER=ubuntu SSHBOX_PASS=your-password \
//       sshbox inspect
//
// Commands:
//
//   inspect            Run inventory on the remote (Python/GPU/CPU/disk/memory)
//   run <cmd...>       Execute a single command, stream output
//   upload <l> <r>     Copy a local file or directory to the remote (SFTP)
//
// Excludes from uploads by default: .venv, __pycache__, .git, runs/, etc.

package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

const usage = `sshbox — SSH/SFTP deploy tool

Usage:
  sshbox inspect
  sshbox run <command...>
  sshbox run --pty <command...>      # allocate a PTY (nicer tqdm output)
  sshbox run --detach [--log=PATH] <command...>
                                       # start a job that outlives the session
                                       # (default log: ~/sshbox-run.log)
  sshbox upload <local> <remote> [--exclude=pat,pat]
  sshbox wait <remote-log> [--marker=STR] [--poll=SEC] [--timeout=SEC]
                                       # block until marker appears in log
                                       # default marker: "Training complete"

Env:
  SSHBOX_HOST       remote hostname/IP        (required)
  SSHBOX_USER       remote username           (required)
  SSHBOX_KEY        private key path          (default: first ~/.ssh/id_*)
  SSHBOX_KEY_PASS   passphrase for that key   (if encrypted)
  SSHBOX_PASS       remote password           (env only; key preferred)
  SSHBOX_PORT       SSH port                  (default 22)
  SSHBOX_REMOTE_DIR default remote workdir    (default ~/box-vision)
`

func main() {
	if len(os.Args) < 2 {
		fmt.Print(usage)
		os.Exit(2)
	}
	sub := os.Args[1]
	rest := os.Args[2:]

	cfg, err := LoadConfig()
	if err != nil {
		fmt.Fprintln(os.Stderr, "sshbox: config error:", err)
		fmt.Fprint(os.Stderr, "\n"+usage)
		os.Exit(2)
	}

	client, err := Dial(cfg)
	if err != nil {
		fmt.Fprintln(os.Stderr, "sshbox: dial error:", err)
		os.Exit(1)
	}
	defer client.Close()

	switch sub {
	case "inspect":
		exit(cmdInspect(client))

	case "run":
		pty := false
		detach := false
		logPath := ""
		for len(rest) > 0 && strings.HasPrefix(rest[0], "--") {
			switch {
			case rest[0] == "--pty":
				pty = true
			case rest[0] == "--detach":
				detach = true
			case strings.HasPrefix(rest[0], "--log="):
				logPath = strings.TrimPrefix(rest[0], "--log=")
			default:
				fmt.Fprintf(os.Stderr, "sshbox: unknown flag %s\n", rest[0])
				os.Exit(2)
			}
			rest = rest[1:]
		}
		if len(rest) == 0 {
			fmt.Fprintln(os.Stderr, "sshbox: run requires a command")
			os.Exit(2)
		}
		if detach {
			if pty {
				// A PTY keeps the channel open by design, which is the exact
				// thing --detach exists to avoid.
				fmt.Fprintln(os.Stderr, "sshbox: --detach cannot be combined with --pty")
				os.Exit(2)
			}
			exit(cmdRunDetached(client, strings.Join(rest, " "), logPath))
			// Exit without unwinding: the job is detached and there is nothing
			// left to do here. Closing the connection politely would wait on a
			// channel the remote job may still hold, which is the very wait
			// --detach exists to avoid.
			os.Exit(0)
		}
		exit(cmdRun(client, strings.Join(rest, " "), pty))

	case "upload":
		if len(rest) < 2 {
			fmt.Fprintln(os.Stderr, "sshbox: upload requires <local> <remote>")
			os.Exit(2)
		}
		local, remote := rest[0], rest[1]
		var extra []string
		for _, arg := range rest[2:] {
			if strings.HasPrefix(arg, "--exclude=") {
				extra = strings.Split(strings.TrimPrefix(arg, "--exclude="), ",")
			}
		}
		exit(cmdUpload(client, local, remote, extra))

	case "wait":
		if len(rest) < 1 {
			fmt.Fprintln(os.Stderr, "sshbox: wait requires <remote-log-path>")
			os.Exit(2)
		}
		logPath := rest[0]
		marker := "Training complete"
		poll := 30
		timeout := 0
		tail := 40
		for _, arg := range rest[1:] {
			switch {
			case strings.HasPrefix(arg, "--marker="):
				marker = strings.TrimPrefix(arg, "--marker=")
			case strings.HasPrefix(arg, "--poll="):
				if n, err := strconv.Atoi(strings.TrimPrefix(arg, "--poll=")); err == nil {
					poll = n
				}
			case strings.HasPrefix(arg, "--timeout="):
				if n, err := strconv.Atoi(strings.TrimPrefix(arg, "--timeout=")); err == nil {
					timeout = n
				}
			case strings.HasPrefix(arg, "--tail="):
				if n, err := strconv.Atoi(strings.TrimPrefix(arg, "--tail=")); err == nil {
					tail = n
				}
			}
		}
		exit(cmdWait(client, logPath, marker, poll, timeout, tail))

	case "-h", "--help", "help":
		fmt.Print(usage)

	default:
		fmt.Fprintf(os.Stderr, "sshbox: unknown command %q\n\n%s", sub, usage)
		os.Exit(2)
	}
}

func exit(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "sshbox:", err)
		os.Exit(1)
	}
}

// Package main: sshbox — SSH/SFTP client tailored to BoxVision deploys.
//
// This file owns the connection lifecycle: SSH config (key or password auth), known-hosts
// handling, command streaming, and SFTP file transfer. Higher-level commands live
// in cmds.go.

package main

import (
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/pkg/sftp"
	"golang.org/x/crypto/ssh"
	"golang.org/x/crypto/ssh/knownhosts"
)

type Client struct {
	cfg  Config
	ssh  *ssh.Client
	sftp *sftp.Client
}

// authMethods builds the auth chain: a private key when one is configured,
// then a password if set.
//
// Key first, deliberately. A server that offers both will accept whichever we
// present, and a key is the stronger credential — the README already tells
// users to prefer one, so the tool should too rather than quietly using the
// password it also happens to have.
func authMethods(cfg Config) ([]ssh.AuthMethod, error) {
	var methods []ssh.AuthMethod

	if cfg.KeyPath != "" {
		pem, err := os.ReadFile(cfg.KeyPath)
		if err != nil {
			return nil, fmt.Errorf("read key %s: %w", cfg.KeyPath, err)
		}
		var signer ssh.Signer
		if cfg.KeyPass != "" {
			signer, err = ssh.ParsePrivateKeyWithPassphrase(pem, []byte(cfg.KeyPass))
		} else {
			signer, err = ssh.ParsePrivateKey(pem)
		}
		if err != nil {
			// Name the fix: an encrypted key fails here with an opaque error
			// otherwise, and the passphrase env var is not guessable.
			if _, ok := err.(*ssh.PassphraseMissingError); ok {
				return nil, fmt.Errorf("key %s is encrypted — set SSHBOX_KEY_PASS", cfg.KeyPath)
			}
			return nil, fmt.Errorf("parse key %s: %w", cfg.KeyPath, err)
		}
		methods = append(methods, ssh.PublicKeys(signer))
	}

	if cfg.Password != "" {
		methods = append(methods, ssh.Password(cfg.Password))
	}
	if len(methods) == 0 {
		return nil, errors.New("no credential: set SSHBOX_KEY or SSHBOX_PASS")
	}
	return methods, nil
}

// Dial opens an SSH connection using key or password auth, validating the host
// key against ~/.ssh/known_hosts (auto-adding on first contact).
func Dial(cfg Config) (*Client, error) {
	hostKeyCb, err := hostKeyCallback()
	if err != nil {
		return nil, fmt.Errorf("known_hosts: %w", err)
	}
	auth, err := authMethods(cfg)
	if err != nil {
		return nil, err
	}
	sshCfg := &ssh.ClientConfig{
		User:            cfg.User,
		Auth:            auth,
		HostKeyCallback: hostKeyCb,
		Timeout:         15 * time.Second,
	}
	addr := net.JoinHostPort(cfg.Host, fmt.Sprint(cfg.Port))
	conn, err := ssh.Dial("tcp", addr, sshCfg)
	if err != nil {
		return nil, fmt.Errorf("dial %s: %w", addr, err)
	}
	return &Client{cfg: cfg, ssh: conn}, nil
}

// RunDetached starts a command and returns without waiting for it.
//
// Run() cannot be reused here. It waits for the stdout/stderr pipes to reach
// EOF, and those close only when every process holding the channel's
// descriptors exits — which for a backgrounded job means waiting for the very
// thing we are trying not to wait for. Even with the remote fds redirected,
// the session outlives the shell often enough to be useless in practice.
//
// So: start the command, give it a moment to report, then close the session.
// The remote side is wrapped in setsid with its descriptors redirected, so the
// job survives the channel going away.
func (c *Client) RunDetached(cmd string, grace time.Duration) error {
	sess, err := c.ssh.NewSession()
	if err != nil {
		return err
	}
	defer sess.Close()

	stdout, err := sess.StdoutPipe()
	if err != nil {
		return err
	}
	if err := sess.Start(cmd); err != nil {
		return err
	}

	// Surface the confirmation line if it arrives quickly; never block on it.
	done := make(chan struct{})
	go func() {
		defer close(done)
		buf := make([]byte, 4096)
		n, _ := stdout.Read(buf)
		if n > 0 {
			os.Stdout.Write(buf[:n])
		}
	}()
	select {
	case <-done:
	case <-time.After(grace):
	}
	return nil
}

// Run executes a command on the remote, streaming stdout+stderr to the local
// terminal. Returns the remote exit code.
func (c *Client) Run(cmd string, pty bool) (int, error) {
	sess, err := c.ssh.NewSession()
	if err != nil {
		return -1, err
	}
	defer sess.Close()

	if pty {
		modes := ssh.TerminalModes{
			ssh.ECHO:          0,
			ssh.TTY_OP_ISPEED: 14400,
			ssh.TTY_OP_OSPEED: 14400,
		}
		if err := sess.RequestPty("xterm-256color", 40, 120, modes); err != nil {
			return -1, fmt.Errorf("pty: %w", err)
		}
	}

	stdout, err := sess.StdoutPipe()
	if err != nil {
		return -1, err
	}
	stderr, err := sess.StderrPipe()
	if err != nil {
		return -1, err
	}

	if err := sess.Start(cmd); err != nil {
		return -1, err
	}

	var wg sync.WaitGroup
	wg.Add(2)
	go pump(&wg, stdout, os.Stdout)
	go pump(&wg, stderr, os.Stderr)
	wg.Wait()

	if err := sess.Wait(); err != nil {
		if exitErr, ok := err.(*ssh.ExitError); ok {
			return exitErr.ExitStatus(), nil
		}
		return -1, err
	}
	return 0, nil
}

func pump(wg *sync.WaitGroup, src io.Reader, dst io.Writer) {
	defer wg.Done()
	_, _ = io.Copy(dst, src)
}

// openSFTP lazily opens an SFTP subsystem on the existing SSH connection.
func (c *Client) openSFTP() (*sftp.Client, error) {
	if c.sftp != nil {
		return c.sftp, nil
	}
	s, err := sftp.NewClient(c.ssh)
	if err != nil {
		return nil, err
	}
	c.sftp = s
	return s, nil
}

// RemoteHome returns the remote user's home directory (the SFTP session cwd).
func (c *Client) RemoteHome() (string, error) {
	s, err := c.openSFTP()
	if err != nil {
		return "", err
	}
	return s.Getwd()
}

// MkdirAll creates a remote directory tree.
func (c *Client) MkdirAll(path string) error {
	s, err := c.openSFTP()
	if err != nil {
		return err
	}
	return s.MkdirAll(path)
}

// Upload copies a single local file to a remote path. Parent dirs are created.
func (c *Client) Upload(localPath, remotePath string) (int64, error) {
	s, err := c.openSFTP()
	if err != nil {
		return 0, err
	}
	if err := s.MkdirAll(filepath.Dir(remotePath)); err != nil {
		return 0, fmt.Errorf("mkdir %s: %w", filepath.Dir(remotePath), err)
	}
	src, err := os.Open(localPath)
	if err != nil {
		return 0, err
	}
	defer src.Close()
	dst, err := s.Create(remotePath)
	if err != nil {
		return 0, err
	}
	defer dst.Close()
	return io.Copy(dst, src)
}

// Close releases SFTP + SSH resources.
func (c *Client) Close() {
	if c.sftp != nil {
		_ = c.sftp.Close()
	}
	if c.ssh != nil {
		_ = c.ssh.Close()
	}
}

func hostKeyCallback() (ssh.HostKeyCallback, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return nil, err
	}
	khPath := filepath.Join(home, ".ssh", "known_hosts")
	// Ensure the file exists so knownhosts.New doesn't error out on first contact.
	if _, err := os.Stat(khPath); os.IsNotExist(err) {
		if err := os.MkdirAll(filepath.Dir(khPath), 0o700); err != nil {
			return nil, err
		}
		f, err := os.OpenFile(khPath, os.O_CREATE|os.O_WRONLY, 0o600)
		if err != nil {
			return nil, err
		}
		_ = f.Close()
	}
	khChecker, err := knownhosts.New(khPath)
	if err != nil {
		return nil, err
	}
	// TOFU: if the host is unknown, append its key and accept. If known with a
	// different key, refuse (man-in-the-middle protection).
	return func(hostname string, remote net.Addr, key ssh.PublicKey) error {
		err := khChecker(hostname, remote, key)
		if err == nil {
			return nil
		}
		if kErr, ok := err.(*knownhosts.KeyError); ok && len(kErr.Want) == 0 {
			f, ferr := os.OpenFile(khPath, os.O_APPEND|os.O_WRONLY, 0o600)
			if ferr != nil {
				return ferr
			}
			defer f.Close()
			line := knownhosts.Line([]string{hostname, remote.String()}, key)
			fmt.Fprintln(os.Stderr, "sshbox: trusting new host key for", hostname)
			_, werr := fmt.Fprintln(f, line)
			return werr
		}
		return err
	}, nil
}

package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// Default exclude patterns when uploading the project tree. Match either by
// basename or path prefix relative to the upload root.
var defaultExcludes = []string{
	".venv", "venv", "env",
	"__pycache__", ".pytest_cache", ".mypy_cache", ".ruff_cache",
	".git",
	"runs", "wandb", "mlruns", "tensorboard_logs",
	"node_modules", ".DS_Store",
	"sshbox/sshbox", // our own compiled binary
}

func cmdInspect(client *Client) error {
	// One short script that reports CPU/GPU/Python/disk/memory in one round-trip.
	script := `set -e
echo "=== UNAME ==="
uname -a
echo "=== PYTHON ==="
python3 --version 2>/dev/null || echo "(python3 not found)"
which uv || echo "(uv not installed)"
echo "=== GPU ==="
if command -v nvidia-smi >/dev/null 2>&1; then
    nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv,noheader
else
    echo "(no nvidia-smi — CPU-only)"
fi
echo "=== CPU ==="
nproc
lscpu | head -5 2>/dev/null || sysctl -n machdep.cpu.brand_string 2>/dev/null
echo "=== MEMORY ==="
free -h | head -2
echo "=== DISK ==="
df -h ~ | tail -1
`
	_, err := client.Run(script, false)
	return err
}

// cmdRunDetached starts a command that outlives the SSH session.
//
// An SSH channel stays open until every process holding its stdout/stderr has
// exited — a backgrounded job inherits those descriptors, so `run 'cmd &'`
// blocks for the whole job even though the shell returned. Redirecting all
// three descriptors severs that inheritance.
//
// This exists because `wait` already assumes a detached job writing to a log,
// and until now nothing here could start one.
func cmdRunDetached(client *Client, command, logPath string) error {
	if logPath == "" {
		logPath = "~/sshbox-run.log"
	}
	// setsid also detaches from the session's process group, so a later
	// hangup cannot take the job down with it.
	wrapped := fmt.Sprintf(
		"mkdir -p \"$(dirname %s)\" 2>/dev/null; setsid sh -c %s > %s 2>&1 < /dev/null & echo \"sshbox: detached, logging to %s\"",
		shellQuote(logPath), shellQuote(command), shellQuote(logPath), logPath,
	)
	return client.RunDetached(wrapped, 5*time.Second)
}

func cmdRun(client *Client, command string, pty bool) error {
	code, err := client.Run(command, pty)
	if err != nil {
		return err
	}
	if code != 0 {
		return fmt.Errorf("remote command exited %d", code)
	}
	return nil
}

// cmdWait blocks until a marker string appears in a remote file, then prints
// a tail of that file and exits. Used to bridge "remote process finished" to
// the local harness's task-completion notification — run it as a background
// task and you get a ping when training is done.
//
// Implementation: a tiny shell loop on the remote that greps the file every
// pollSec seconds. Exits 0 on match, 1 on timeout, 2 if file is missing too
// long.
func cmdWait(client *Client, logPath, marker string, pollSec, timeoutSec int, tailLines int) error {
	if marker == "" {
		marker = "Training complete"
	}
	if pollSec <= 0 {
		pollSec = 30
	}
	if tailLines <= 0 {
		tailLines = 40
	}
	// Resolve leading ~/ remotely (the local shell would otherwise expand it
	// against the local home, pointing at the wrong path).
	if strings.HasPrefix(logPath, "~/") {
		logPath = "$HOME/" + logPath[2:]
	} else if logPath == "~" {
		logPath = "$HOME"
	}
	timeoutClause := ""
	if timeoutSec > 0 {
		timeoutClause = fmt.Sprintf(`if [ $waited -ge %d ]; then echo "sshbox-wait: timeout after %ds" >&2; exit 1; fi`, timeoutSec, timeoutSec)
	}
	// Note: we expand `log` via eval below so $HOME interpolates remotely.
	script := fmt.Sprintf(`
set -u
log=$(eval echo %q)
marker=%q
poll=%d
waited=0
missing=0
echo "sshbox-wait: watching $log for $marker (poll=${poll}s)"
while :; do
    if [ -f "$log" ]; then
        missing=0
        if grep -q -- "$marker" "$log"; then
            echo "sshbox-wait: marker hit at $(date)"
            tail -%d "$log" | tr -d '\r'
            exit 0
        fi
    else
        missing=$((missing + poll))
        if [ $missing -ge 300 ]; then
            echo "sshbox-wait: log not found for 5+ minutes: $log" >&2
            exit 2
        fi
    fi
    sleep $poll
    waited=$((waited + poll))
    %s
done
`, logPath, marker, pollSec, tailLines, timeoutClause)

	code, err := client.Run(script, false)
	if err != nil {
		return err
	}
	if code != 0 {
		return fmt.Errorf("remote wait exited %d", code)
	}
	return nil
}

// cmdUpload copies a local file or directory to the remote.
//
// extraExcludes is matched against either basename or path-relative-to-root.
func cmdUpload(client *Client, local, remote string, extraExcludes []string) error {
	// SFTP has no shell, so a quoted "~/path" arrives literally and would
	// create a directory named "~". Expand it against the remote home.
	if remote == "~" || strings.HasPrefix(remote, "~/") {
		home, err := client.RemoteHome()
		if err != nil {
			return fmt.Errorf("expanding ~ in remote path: %w", err)
		}
		remote = home + strings.TrimPrefix(remote, "~")
	}
	info, err := os.Stat(local)
	if err != nil {
		return err
	}
	excludes := append([]string{}, defaultExcludes...)
	excludes = append(excludes, extraExcludes...)

	if !info.IsDir() {
		n, err := client.Upload(local, remote)
		if err != nil {
			return err
		}
		fmt.Printf("uploaded %s → %s (%.2f MB)\n", local, remote, float64(n)/1024/1024)
		return nil
	}

	root := filepath.Clean(local)
	if err := client.MkdirAll(remote); err != nil {
		return err
	}

	var nFiles int
	var nBytes int64
	err = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(root, path)
		if rel == "." {
			return nil
		}
		if isExcluded(rel, d.Name(), excludes) {
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		remotePath := filepath.ToSlash(filepath.Join(remote, rel))
		if d.IsDir() {
			return client.MkdirAll(remotePath)
		}
		n, uerr := client.Upload(path, remotePath)
		if uerr != nil {
			return fmt.Errorf("upload %s: %w", rel, uerr)
		}
		nFiles++
		nBytes += n
		fmt.Printf("  %s  (%.1f KB)\n", rel, float64(n)/1024)
		return nil
	})
	if err != nil {
		return err
	}
	fmt.Printf("uploaded %d files, %.2f MB → %s\n", nFiles, float64(nBytes)/1024/1024, remote)
	return nil
}

func isExcluded(relPath, basename string, patterns []string) bool {
	relPath = filepath.ToSlash(relPath)
	for _, p := range patterns {
		if p == basename {
			return true
		}
		if p == relPath {
			return true
		}
		if strings.HasPrefix(relPath, p+"/") {
			return true
		}
		// Suffix glob: "*.zip" style
		if strings.HasPrefix(p, "*") && strings.HasSuffix(basename, p[1:]) {
			return true
		}
	}
	return false
}

// shellQuote wraps a string for safe use inside a remote sh command.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// Config holds connection details. Credentials are read from the environment
// only — never passed on the command line, so they don't end up in shell
// history or process listings.
type Config struct {
	Host      string
	Port      int
	User      string
	Password  string
	KeyPath   string // private key; takes precedence over Password
	KeyPass   string // passphrase for an encrypted key
	RemoteDir string // default working dir for deploy commands
}

func LoadConfig() (Config, error) {
	cfg := Config{
		Host:      getenv("SSHBOX_HOST", ""),
		User:      getenv("SSHBOX_USER", ""),
		Password:  os.Getenv("SSHBOX_PASS"),
		KeyPath:   os.Getenv("SSHBOX_KEY"),
		KeyPass:   os.Getenv("SSHBOX_KEY_PASS"),
		RemoteDir: getenv("SSHBOX_REMOTE_DIR", "~/box-vision"),
	}

	// A key given without an explicit path is the common case; fall back to the
	// usual identities so `SSHBOX_KEY=1`-style setups aren't needed.
	if cfg.KeyPath == "" && cfg.Password == "" {
		cfg.KeyPath = defaultIdentity()
	}
	cfg.KeyPath = expandHome(cfg.KeyPath)

	if v := os.Getenv("SSHBOX_PORT"); v != "" {
		p, err := strconv.Atoi(v)
		if err != nil {
			return cfg, fmt.Errorf("SSHBOX_PORT: %w", err)
		}
		cfg.Port = p
	}
	if cfg.Port == 0 {
		cfg.Port = 22
	}

	// Tilde expansion happens server-side. Just trim trailing slash for tidiness.
	cfg.RemoteDir = strings.TrimRight(cfg.RemoteDir, "/")

	var missing []string
	if cfg.Host == "" {
		missing = append(missing, "SSHBOX_HOST")
	}
	if cfg.User == "" {
		missing = append(missing, "SSHBOX_USER")
	}
	// Either credential satisfies the requirement; naming both keeps the error
	// useful for someone who set neither.
	if cfg.Password == "" && cfg.KeyPath == "" {
		missing = append(missing, "SSHBOX_KEY or SSHBOX_PASS")
	}
	if len(missing) > 0 {
		return cfg, errors.New("missing required env vars: " + strings.Join(missing, ", "))
	}
	return cfg, nil
}

// defaultIdentity returns the first standard private key that exists, so a
// user with a normal ~/.ssh setup needs no configuration at all.
func defaultIdentity() string {
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	for _, name := range []string{"id_ed25519", "id_ecdsa", "id_rsa"} {
		path := filepath.Join(home, ".ssh", name)
		if _, err := os.Stat(path); err == nil {
			return path
		}
	}
	return ""
}

// expandHome resolves a leading ~/ locally — unlike remote paths, this one is
// never handed to a shell that could do it for us.
func expandHome(path string) string {
	if !strings.HasPrefix(path, "~/") {
		return path
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return path
	}
	return filepath.Join(home, path[2:])
}

func getenv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}
